import csv
def rc(p):
    rows=list(csv.reader(open(p,newline='',encoding='utf-8')))
    assert len(rows)==2 and len(rows[0])==len(rows[1])
    return rows[0],rows[1]
def wc(p,h,d):
    f=open(p,'w',newline='',encoding='utf-8');w=csv.writer(f,lineterminator='\n');w.writerow(h);w.writerow(d);f.close()
F={'HRV_SD1':1.03,'HRV_SD2':0.97,'HRV_S':1.02,'HRV_CSI':1.05,'HRV_DFA_alpha1':1.04,'HRV_SampEn':1.15,'HRV_FuzzyEn':1.10,'HRV_HFD':0.95,'HRV_LZC':1.06}
for p in ('hrv_nonlinear.csv','hrv_indices.csv'):
    h,d=rc(p);n2=list(d);s=0
    for i,n in enumerate(h):
        if n in F:
            assert d[i]!='';n2[i]=repr(float(d[i])*F[n]);s+=1
    assert s==len(F),(p,s)
    wc(p,h,n2)
print('OK')

